#!/usr/bin/env bun
// reverse-engineer-anything — session-lock CLI for the REA MCP gate.
//
//   ob-plugin-reverse-engineer-anything-mcp open [--ttl N]   unlock the MCP for this thread's work
//   ob-plugin-reverse-engineer-anything-mcp close            lock it again (always do this after analysis)
//   ob-plugin-reverse-engineer-anything-mcp status           lock state, REA version, readiness, gate log tail
//   ob-plugin-reverse-engineer-anything-mcp gate             speak MCP JSON-RPC to the gate directly (fallback
//                                                            for threads that do not see rea_* tools yet)
//
// The gate (MCP server) reads ~/.open-bot/plugin-reverse-engineer-anything/session.json;
// this CLI is the only writer. No secrets involved.
import { existsSync, mkdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";

const PLUGIN_ID = "reverse-engineer-anything";
const HOME = process.env.HOME || "/home/agent";
const STATE_DIR = `${HOME}/.open-bot/plugin-${PLUGIN_ID}`;
const SESSION_FILE = `${STATE_DIR}/session.json`;
const LOG_FILE = `${STATE_DIR}/gate.log`;
const CONFIG_FILE = `${HOME}/.config/open-bot/plugin-${PLUGIN_ID}.json`;
const PIN_FALLBACK = "6.7.0";

function settings(): Record<string, string> {
  try { return JSON.parse(readFileSync(CONFIG_FILE, "utf8")).settings || {}; } catch { return {}; }
}
function defaultTtlMinutes(): number {
  const n = Number(settings().ttl_minutes ?? 240);
  return Number.isFinite(n) && n > 0 ? n : 240;
}
// Daemon-spawned contexts may run with a minimal PATH that lacks /usr/local/bin,
// so fall back to the standard global-install locations before giving up.
const REA_FALLBACKS = ["/usr/local/bin/rea", "/usr/bin/rea", `${HOME}/.local/bin/rea`];
function reaBin(): string | null {
  const found = Bun.which("rea");
  if (found) return found;
  for (const p of REA_FALLBACKS) {
    try { if (existsSync(p)) return p; } catch { /* ignore */ }
  }
  return null;
}
function reaVersion(): string {
  const p = reaBin();
  if (!p) return "NOT INSTALLED";
  try {
    const r = Bun.spawnSync([p, "--version"]);
    return r.stdout.toString().trim() || "installed (version unknown)";
  } catch { return "installed (version check failed)"; }
}
function psOk(): boolean { return !!Bun.which("ps") || existsSync("/usr/bin/ps"); }
function session(): { expires: number } | null {
  try {
    const s = JSON.parse(readFileSync(SESSION_FILE, "utf8"));
    return typeof s.expires === "number" ? s : null;
  } catch { return null; }
}
function isOpen(): boolean { const s = session(); return !!s && s.expires > Date.now(); }
function gateLogTail(lines = 8): string[] {
  try {
    return readFileSync(LOG_FILE, "utf8").trimEnd().split("\n").slice(-lines);
  } catch { return []; }
}

const [, , cmd = "status"] = process.argv;

if (cmd === "open") {
  const ttlIdx = process.argv.indexOf("--ttl");
  const explicit = ttlIdx > -1 ? Number(process.argv[ttlIdx + 1]) : undefined;
  const minutes = Math.min(1440, Math.max(1, explicit && Number.isFinite(explicit) ? explicit : defaultTtlMinutes()));
  if (!reaBin()) {
    console.error("The REA CLI is NOT installed. Reinstall the plugin (its setup installs rea-agents), then retry.");
    process.exit(1);
  }
  mkdirSync(STATE_DIR, { recursive: true });
  const expires = Date.now() + minutes * 60_000;
  writeFileSync(SESSION_FILE, JSON.stringify({ expires, openedAt: new Date().toISOString() }, null, 2));
  console.log(`REA MCP session OPEN for ${minutes} min (until ${new Date(expires).toISOString()}).`);
  console.log(`Work through the rea_* MCP tools (rea_catalog to discover, rea_cli to run), then run \`ob-plugin-${PLUGIN_ID}-mcp close\` when the analysis is delivered.`);
  process.exit(0);
}

if (cmd === "close") {
  try { rmSync(SESSION_FILE); } catch { /* already closed */ }
  console.log("REA MCP session CLOSED (gate locked).");
  process.exit(0);
}

if (cmd === "gate") {
  // Fallback endpoint: speak MCP JSON-RPC (one message per line) through the gate's lock.
  // For threads whose tool list does not show rea_* yet (e.g. right after install,
  // before the desktop restarts). Same enforcement as the registered MCP server.
  const gate = `${HOME}/.open-bot/plugin-${PLUGIN_ID}/gate.ts`;
  const gatePath = existsSync(gate) ? gate : `/usr/local/bin/ob-plugin-${PLUGIN_ID}-gate.ts`;
  const child = Bun.spawn(["bun", gatePath], { stdin: "inherit", stdout: "inherit", stderr: "inherit" });
  process.exit(await child.exited);
}

if (cmd === "status") {
  const s = session();
  const open = isOpen();
  const minsLeft = open && s ? Math.max(0, Math.round((s.expires - Date.now()) / 60_000)) : 0;
  console.log(`gate:   ${open ? `OPEN (${minsLeft} min left)` : s ? "EXPIRED (run open again)" : "LOCKED"}`);
  console.log(`rea:    ${reaVersion()}`);
  console.log(`procps: ${psOk() ? "ok" : "MISSING — apt-get install procps (Linux prerequisite)"}`);
  console.log(`settings: ttl_minutes=${settings().ttl_minutes ?? "240 (default)"} timeout_minutes=${settings().timeout_minutes ?? "15 (default)"} rea_version=${settings().rea_version ?? `${PIN_FALLBACK} (default)`} rea_env=${settings().rea_env ? "(set)" : "(none)"}`);
  const tail = gateLogTail();
  if (tail.length) console.log(`gate.log (last ${tail.length}):\n  ` + tail.join("\n  "));
  process.exit(0);
}

console.error(`usage: ob-plugin-${PLUGIN_ID}-mcp open [--ttl N] | close | status | gate`);
process.exit(2);

#!/usr/bin/env bun
// reverse-engineer-anything — Ghidra headless companion CLI.
//
//   ob-plugin-reverse-engineer-anything-ghidra readiness
//     Prints a ghidra-only verdict as JSON. Exit 0 = ready, 1 = not ready.
//     Shell scripts can test the exit code (rea doctor exits 1 whenever ANY
//     optional engine is missing, which is the normal state here).
//
//   ob-plugin-reverse-engineer-anything-ghidra run [--timeout MIN] -- <analyzeHeadless args...>
//     Runs analyzeHeadless with the plugin-managed env (Ghidra dir + JDK 21+),
//     inheriting stdio, e.g. an existing-project re-read without re-analysis:
//       run -- /path/ghidra-proj MyProj -process D2Game.dll -noanalysis \
//            -scriptPath /path/scripts -postScript DisasmOne.java 6fcb8200 /tmp/out.asm
//     Exit codes: 0 ok · 1 ghidra/JDK not ready · 2 another Ghidra run holds the
//     lock · 3 usage · 124 timed out · otherwise analyzeHeadless's own code.
//
// The same lock file gates the rea_ghidra MCP tool: one native analysis at a time
// across both entry points. No secrets involved. Companion-optional by design:
// nothing here requires the rea CLI to exist.
import { closeSync, existsSync, mkdirSync, openSync, readdirSync, readFileSync, unlinkSync, writeSync } from "node:fs";

const PLUGIN_ID = "reverse-engineer-anything";
const HOME = process.env.HOME || "/home/agent";
const STATE_DIR = `${HOME}/.open-bot/plugin-${PLUGIN_ID}`;
const LOCK_FILE = `${STATE_DIR}/ghidra.lock`;
const CONFIG_FILE = `${HOME}/.config/open-bot/plugin-${PLUGIN_ID}.json`;

function settings(): Record<string, string> {
  try { return JSON.parse(readFileSync(CONFIG_FILE, "utf8")).settings || {}; } catch { return {}; }
}
function ghidraDir(): string {
  const s = String(settings().ghidra_install_dir ?? "").trim();
  if (s) return s; // configured (even if missing — readiness surfaces the gap)
  if (existsSync("/opt/ghidra/current/support/analyzeHeadless")) return "/opt/ghidra/current";
  return "";
}
function javaHomeDir(): string {
  const envHome = String(process.env.JAVA_HOME ?? "").trim();
  if (envHome && existsSync(envHome)) return envHome;
  if (existsSync("/opt/java/current")) return "/opt/java/current";
  try {
    const pick = readdirSync("/usr/lib/jvm")
      .filter((d) => /java-2[1-9]-openjdk/.test(d))
      .sort()
      .pop();
    if (pick) return `/usr/lib/jvm/${pick}`;
  } catch { /* no jvm dir */ }
  return "";
}
function readiness() {
  const dir = ghidraDir();
  const headless = dir ? `${dir}/support/analyzeHeadless` : "";
  const home = javaHomeDir();
  const javaOnPath = !!Bun.which("java");
  const ready = !!dir && existsSync(headless) && ((!!home && existsSync(`${home}/bin/java`)) || javaOnPath);
  return {
    ready,
    ghidra_dir: dir || null,
    analyzeHeadless: dir && existsSync(headless) ? headless : null,
    java_home: home || null,
    java_on_path: javaOnPath,
    remediation: ready ? null :
      "Set the plugin setting ghidra_install_dir to a Ghidra install containing support/analyzeHeadless, and provide a JDK 21+ (JAVA_HOME or java on PATH). The plugin setup normally lays both down at /opt/ghidra and /opt/java.",
  };
}
function pidAlive(pid: number): boolean {
  try { process.kill(pid, 0); return true; } catch (e: any) { return e?.code !== "ESRCH"; }
}
function acquireLock(): { ok: boolean; holder: string } {
  mkdirSync(STATE_DIR, { recursive: true });
  try {
    const { pid, at } = JSON.parse(readFileSync(LOCK_FILE, "utf8"));
    const stale = typeof pid !== "number" || !pidAlive(pid) || Date.now() - (at ?? 0) > 65 * 60_000;
    if (!stale) return { ok: false, holder: `pid ${pid} since ${new Date(at ?? 0).toISOString()}` };
    try { unlinkSync(LOCK_FILE); } catch { /* raced */ }
  } catch { /* no lock held */ }
  try {
    const fd = openSync(LOCK_FILE, "wx");
    writeSync(fd, JSON.stringify({ pid: process.pid, at: Date.now() }));
    closeSync(fd);
    return { ok: true, holder: "" };
  } catch {
    return { ok: false, holder: "another ghidra run just started" };
  }
}
function releaseLock() { try { unlinkSync(LOCK_FILE); } catch { /* gone */ } }

const USAGE =
  "usage: ob-plugin-reverse-engineer-anything-ghidra readiness\n" +
  "       ob-plugin-reverse-engineer-anything-ghidra run [--timeout MIN] -- <analyzeHeadless args...>";

const [, , cmd] = process.argv;

if (cmd === "readiness") {
  const r = readiness();
  console.log(JSON.stringify(r, null, 2));
  process.exit(r.ready ? 0 : 1);
}

if (cmd === "run") {
  const rest = process.argv.slice(3);
  const sep = rest.indexOf("--");
  if (sep < 0) { console.error(USAGE); process.exit(3); }
  let timeoutMin = 15;
  const flags = rest.slice(0, sep);
  for (let i = 0; i < flags.length; i++) {
    if (flags[i] === "--timeout") {
      const n = Number(flags[i + 1]);
      if (!Number.isFinite(n) || n <= 0) { console.error("run: --timeout expects minutes > 0"); process.exit(3); }
      timeoutMin = Math.min(60, n);
      i++;
    } else { console.error(USAGE); process.exit(3); }
  }
  const args = rest.slice(sep + 1).filter((a) => a.length > 0);
  if (!args.length) { console.error(USAGE); process.exit(3); }
  const r = readiness();
  if (!r.ready || !r.analyzeHeadless) {
    console.error(JSON.stringify(r, null, 2));
    process.exit(1);
  }
  const lock = acquireLock();
  if (!lock.ok) {
    console.error(`Another Ghidra analysis is already running (${lock.holder}). One native analysis at a time.`);
    process.exit(2);
  }
  const env: Record<string, string> = { ...process.env };
  if (r.java_home) {
    env.JAVA_HOME = r.java_home;
    env.PATH = `${r.java_home}/bin:${env.PATH || ""}`;
  }
  let timedOut = false;
  let child: ReturnType<typeof Bun.spawn> | null = null;
  const timer = setTimeout(() => { timedOut = true; try { child?.kill(); } catch { /* gone */ } }, timeoutMin * 60_000);
  child = Bun.spawn([r.analyzeHeadless, ...args], { stdin: "inherit", stdout: "inherit", stderr: "inherit", env });
  const code = await child.exited;
  clearTimeout(timer);
  releaseLock();
  process.exit(timedOut ? 124 : (code ?? 1));
}

console.error(USAGE);
process.exit(3);
